"""Print or patch effective EtherCAT state-request access settings for a TwinCAT project.

Without any flags added, can print a report which shows caput permission (ASG/DISP) and
internal-processing permission (DISA/DISV) for each non-passive ethercat terminal.
Missing terminal rules are printed as denied.

Use the --patch flag to reconcile devices in an existing access file. By default,
permission will be asked before applying changes. Add the --yes flag to apply the
reported changes without prompting.

Example:
  pytmc ethercat_access project.tsproj \
    --config iocBoot/ioc-test/TestIOC_ethercat_state_access.cmd
  pytmc ethercat_access project.tsproj \
    --config access.cmd --patch
  pytmc ethercat_access project.tsproj \
    --config access.cmd --patch --yes
"""

import argparse
import sys
from pathlib import Path

from .. import ethercat, parser


def build_arg_parser(argparser=None):
    if argparser is None:
        argparser = argparse.ArgumentParser()
    argparser.description = __doc__
    argparser.add_argument("project", help="TwinCAT .tsproj project")
    argparser.add_argument(
        "--config",
        required=True,
        help=(
            "Generated IOC-shell EtherCAT state-access file "
            "(*_ethercat_state_access.cmd)"
        ),
    )
    argparser.add_argument(
        "--patch",
        action="store_true",
        help="Compare devices and update the access file after confirmation",
    )
    argparser.add_argument(
        "--yes",
        action="store_true",
        help="Apply --patch changes without prompting",
    )
    return argparser


def main(project, config, patch=False, yes=False):
    if yes and not patch:
        raise ValueError("--yes requires --patch")

    parsed_project = parser.parse(project)
    terminals = ethercat.get_ethercat_terminals(parsed_project)
    if not patch:
        ethercat.print_access_report(terminals, config, sys.stdout)
        return

    added, removed = ethercat.access_config_device_changes(terminals, config)
    if not added and not removed:
        print("no ethercat device changes found")
        return

    print("EtherCAT device changes:")
    for terminal in removed:
        print(f"  Remove port={terminal.port} device={terminal.name}")
    for terminal in added:
        print(f"  Add port={terminal.port} device={terminal.name}")

    if not yes:
        response = input("Apply these changes? [y/N] ")
        if response.strip().lower() not in ("y", "yes"):
            print("No changes applied.")
            return

    updated_config = ethercat.render_updated_access_config(terminals, config)
    Path(config).write_text(updated_config, encoding="utf-8")
    print(f"Updated access file: {config}")
